# Cross-fit comparison of 5 pre-specified bias rules: threshold from fitting-half statistics of the edited margins, applied to the held-out half; pooled over both halves.
def balanced_std_threshold(m, mask, robust=False):
    st=[]
    for k in range(4):
        x = m[mask&(g==k)]
        if robust: mu_ = np.median(x); sd_ = 1.4826*np.median(np.abs(x-mu_))
        else: mu_ = x.mean(); sd_ = x.std()
        st.append((mu_, sd_))
    # maximize over t the minimum standardized distance: landbird groups (0,1): (t-mu)/sd ; waterbird groups (2,3): (mu-t)/sd -> crossing of lower envelopes (piecewise linear), solve exactly
    cands=[]
    for a_ in (0,1):
        for b_ in (2,3):
            (m1,s1),(m2,s2) = st[a_], st[b_]; t = (m1*s2+m2*s1)/(s1+s2); cands.append(t)
    def minz(t): return min(min((t-st[k][0])/st[k][1] for k in (0,1)), min((st[k][0]-t)/st[k][1] for k in (2,3)))
    t_best = max(cands, key=minz); return t_best
def rules_for(m, fitmask, orig_centroid_margin):
