    out['d original bias (pure mean-ablation)'] = cen - orig_centroid_margin    # margins here are centered: centered = uncentered - orig_centroid_margin  => uncentered>0 <=> centered > -orig_centroid_margin
    out['e halfway a-d'] = 0.5*(out['a centroid']+out['d original bias (pure mean-ablation)'])
